const body = $input.first().json.body || $input.first().json;
const name = (body.lead_name || '').split(' ')[0] || 'there';
const biz = body.business_name || 'ELION';
const date = body.booking_date || 'TBD';
const time = body.booking_time || 'TBD';
const link = body.meeting_link || 'https://meet.google.com/new';
const msg = 'Hi ' + name + ',

Your booking with ' + biz + ' has been confirmed.

Date: ' + date + '
Time: ' + time + '
Link: ' + link + '

Please join from somewhere you can comfortably discuss your business.

Best regards,
' + biz;
return [{ json: { lead_email: body.lead_email, lead_name: body.lead_name, business_name: biz, message: msg, booking_date: date, booking_time: time, meeting_link: link } }];
